SELECT order_id AS "orderId", user_id AS "userId", order_type AS "orderType", total_amount AS "totalAmount", status AS "status", create_at AS "createAt" FROM orders WHERE user_id = #{userId} AND delete_at IS NULL
AND status = #{status}
ORDER BY create_at DESC NULLS LAST, order_id DESC LIMIT #{limit} OFFSET #{offset}
